-- Conceptual: Customer places Order; Order contains Product (many-to-many)
CREATE TABLE customer (
    id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email  text NOT NULL UNIQUE,
    name   text NOT NULL
);
CREATE TABLE product (
    id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name   text NOT NULL,
    price  numeric(10,2) NOT NULL          -- current list price
);
CREATE TABLE orders (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id bigint NOT NULL REFERENCES customer(id),
    placed_at   timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE order_line (
    order_id   bigint NOT NULL REFERENCES orders(id),
    product_id bigint NOT NULL REFERENCES product(id),
    quantity   int NOT NULL CHECK (quantity > 0),
    unit_price numeric(10,2) NOT NULL,      -- price actually paid: a fact of the sale
    PRIMARY KEY (order_id, product_id)
);

CREATE TABLE student (id int PRIMARY KEY, name text NOT NULL);
CREATE TABLE course  (id int PRIMARY KEY, title text NOT NULL);

-- M:N via a junction table that carries its own attributes
CREATE TABLE enrollment (
    student_id  int NOT NULL REFERENCES student(id) ON DELETE CASCADE,
    course_id   int NOT NULL REFERENCES course(id),
    enrolled_on date NOT NULL DEFAULT current_date,
    grade       text,
    PRIMARY KEY (student_id, course_id)       -- no duplicate enrollments
);

-- 1:1 optional: at most one profile per student
CREATE TABLE profile (
    student_id int PRIMARY KEY REFERENCES student(id),
    bio        text
);

CREATE TABLE country (
    code char(2) PRIMARY KEY,               -- natural key: stable ISO code
    name text NOT NULL
);
CREATE TABLE app_user (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,  -- surrogate
    email      text NOT NULL,
    country    char(2) NOT NULL REFERENCES country(code),
    CONSTRAINT app_user_email_uk UNIQUE (email)   -- natural key still enforced
);
INSERT INTO country VALUES ('AM', 'Armenia');
INSERT INTO app_user (email, country) VALUES ('ana@example.com', 'AM');
INSERT INTO app_user (email, country) VALUES ('ana@example.com', 'AM');
-- ERROR: duplicate key value violates unique constraint "app_user_email_uk"

-- Not normalised: department name repeated on every employee
-- employee(id, name, dept_id, dept_name)   -- dept_name depends on dept_id

-- 3NF: each fact once
CREATE TABLE department (
    id   int PRIMARY KEY,
    name text NOT NULL UNIQUE
);
CREATE TABLE employee (
    id      int PRIMARY KEY,
    name    text NOT NULL,
    dept_id int NOT NULL REFERENCES department(id)
);
INSERT INTO department VALUES (1, 'Sales');
INSERT INTO employee VALUES (10, 'Ani', 1), (11, 'Narek', 1);
UPDATE department SET name = 'Sales EMEA' WHERE id = 1;  -- one row changes
SELECT e.name, d.name AS dept
FROM employee e JOIN department d ON d.id = e.dept_id;
-- Ani   | Sales EMEA
-- Narek | Sales EMEA

CREATE TABLE orders (id bigint PRIMARY KEY, status text, region text,
                     total numeric, placed_at timestamptz);
-- OLTP: touch a few rows by key, many times per second
SELECT id, status FROM orders WHERE id = 48213;
UPDATE orders SET status = 'paid' WHERE id = 48213;

-- OLAP: scan and aggregate many rows, a few times per hour
SELECT date_trunc('month', placed_at) AS month,
       region,
       sum(total) AS revenue
FROM   orders
WHERE  placed_at >= '2026-01-01'
GROUP  BY 1, 2
ORDER  BY 1, 2;

CREATE TABLE account (id int PRIMARY KEY, balance numeric NOT NULL CHECK (balance >= 0));
INSERT INTO account VALUES (1, 100), (2, 50);

BEGIN;
UPDATE account SET balance = balance + 80 WHERE id = 2;
UPDATE account SET balance = balance - 80 WHERE id = 1;
COMMIT;            -- both changes become visible and durable together

BEGIN;
UPDATE account SET balance = balance + 80 WHERE id = 2;
UPDATE account SET balance = balance - 80 WHERE id = 1;
-- ERROR: violates check constraint (balance would be -60)
ROLLBACK;          -- the credit to account 2 is undone too

SELECT * FROM account ORDER BY id;   -- 1 | 20   2 | 130

CREATE TABLE event (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                    user_id int NOT NULL, kind text NOT NULL);
INSERT INTO event (user_id, kind)
SELECT g % 10000, 'click' FROM generate_series(1, 200000) g;
ANALYZE event;

EXPLAIN SELECT * FROM event WHERE user_id = 42;
-- Seq Scan on event  (filter: user_id = 42)

CREATE INDEX event_user_id_idx ON event (user_id);
EXPLAIN SELECT * FROM event WHERE user_id = 42;
-- Bitmap Heap Scan on event ... -> Bitmap Index Scan on event_user_id_idx

CREATE TABLE post (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                   author text NOT NULL, created_at timestamptz NOT NULL);
INSERT INTO post (author, created_at)
SELECT 'user' || (g % 500), now() - g * interval '1 minute'
FROM generate_series(1, 100000) g;
CREATE INDEX post_created_idx ON post (created_at);
ANALYZE post;

EXPLAIN SELECT * FROM post ORDER BY created_at DESC LIMIT 10;
-- Limit -> Index Scan Backward using post_created_idx on post
-- (no sort: rows come out of the index already ordered)

EXPLAIN SELECT * FROM post WHERE author LIKE '%er4%';
-- Seq Scan on post: no fixed prefix, the B-tree can't help

CREATE TABLE short_link (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                         long_url text NOT NULL);
INSERT INTO short_link (long_url)
SELECT 'https://example.com/articles/' || md5(g::text) || '/' || repeat('x', 100)
FROM generate_series(1, 50000) g;
CREATE INDEX link_url_btree ON short_link USING btree (long_url);
CREATE INDEX link_url_hash  ON short_link USING hash  (long_url);

SELECT relname, pg_size_pretty(pg_relation_size(oid))
FROM pg_class WHERE relname LIKE 'link_url_%';
-- the hash index is several times smaller than the B-tree here

EXPLAIN SELECT id FROM short_link
WHERE long_url BETWEEN 'https://example.com/articles/00' AND 'https://example.com/articles/01';
-- uses the B-tree: hash indexes can't do ranges

CREATE TABLE message (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                      chat_id int NOT NULL, sent_at timestamptz NOT NULL,
                      body text NOT NULL);
INSERT INTO message (chat_id, sent_at, body)
SELECT g % 1000, now() - g * interval '1 second', 'hi'
FROM generate_series(1, 200000) g;
-- equality column first, then the sort column; INCLUDE makes it covering
CREATE INDEX message_chat_sent_idx ON message (chat_id, sent_at DESC) INCLUDE (body);
VACUUM ANALYZE message;

EXPLAIN SELECT sent_at, body FROM message
WHERE chat_id = 7 ORDER BY sent_at DESC LIMIT 20;
-- Limit -> Index Only Scan using message_chat_sent_idx on message

CREATE TABLE author (id int PRIMARY KEY, name text);
CREATE TABLE book (id int PRIMARY KEY, author_id int REFERENCES author(id), title text);
INSERT INTO author SELECT g, 'a' || g FROM generate_series(1, 1000) g;
INSERT INTO book SELECT g, 1 + g % 1000, 't' || g FROM generate_series(1, 100000) g;
CREATE INDEX book_author_idx ON book (author_id);
ANALYZE author; ANALYZE book;

EXPLAIN ANALYZE
SELECT a.name, b.title FROM author a JOIN book b ON b.author_id = a.id
WHERE a.id = 5;
-- Nested Loop (rows=100)  -- one author, then index lookups into book
--   -> Index Scan using author_pkey on author a (rows=1)
--   -> Bitmap Heap Scan on book b (rows=100)

EXPLAIN SELECT a.name, count(*) FROM author a JOIN book b ON b.author_id = a.id
GROUP BY a.name;
-- HashAggregate -> Hash Join (big inputs: build a hash table of author)

CREATE TABLE post    (id int PRIMARY KEY, title text,
                      comment_count int NOT NULL DEFAULT 0);   -- denormalised
CREATE TABLE comment (id int PRIMARY KEY, post_id int REFERENCES post(id), body text);
INSERT INTO post (id, title) VALUES (1, 'Hello');

-- keep the copy in sync in the same transaction as the source write
BEGIN;
INSERT INTO comment VALUES (100, 1, 'First!');
UPDATE post SET comment_count = comment_count + 1 WHERE id = 1;
COMMIT;

-- and keep a way to rebuild it from the source of truth
UPDATE post p SET comment_count = (SELECT count(*) FROM comment c WHERE c.post_id = p.id);
SELECT id, comment_count FROM post;   -- 1 | 1

CREATE TABLE item (id int PRIMARY KEY, stock int NOT NULL);
INSERT INTO item VALUES (1, 10);
-- Lost update at Read Committed, two sessions A and B:
-- A: BEGIN; SELECT stock FROM item WHERE id = 1;   -- 10
-- B: BEGIN; SELECT stock FROM item WHERE id = 1;   -- 10
-- A: UPDATE item SET stock = 9 WHERE id = 1; COMMIT;
-- B: UPDATE item SET stock = 9 WHERE id = 1; COMMIT;  -- one sale lost

-- Fix 1: let the database do the read-modify-write atomically
UPDATE item SET stock = stock - 1 WHERE id = 1 AND stock > 0;

-- Fix 2: lock the row you are about to change
BEGIN;
SELECT stock FROM item WHERE id = 1 FOR UPDATE;   -- B waits here
UPDATE item SET stock = stock - 1 WHERE id = 1;
COMMIT;

-- Fix 3: BEGIN ISOLATION LEVEL SERIALIZABLE; and retry on SQLSTATE 40001

CREATE TABLE post  (id int PRIMARY KEY);
CREATE TABLE photo (id int PRIMARY KEY);
-- polymorphic comment with real foreign keys: exactly one parent
CREATE TABLE comment (
    id       int PRIMARY KEY,
    post_id  int REFERENCES post(id),
    photo_id int REFERENCES photo(id),
    body     text NOT NULL,
    deleted_at timestamptz,                       -- soft delete
    CHECK (num_nonnulls(post_id, photo_id) = 1)
);
-- usernames unique among live rows only
CREATE TABLE member (id int PRIMARY KEY, username text NOT NULL, deleted_at timestamptz);
CREATE UNIQUE INDEX member_username_live ON member (username) WHERE deleted_at IS NULL;
INSERT INTO member VALUES (1, 'ani', now()), (2, 'ani', NULL);   -- ok
INSERT INTO member VALUES (3, 'ani', NULL);
-- ERROR: duplicate key value violates unique constraint "member_username_live"

-- Session A                                 -- Session B
BEGIN;
UPDATE account SET balance = balance - 10
WHERE id = 1;                                -- row 1 locked by A
                                             SELECT balance FROM account WHERE id = 1;
                                             -- returns old value at once (MVCC snapshot)
                                             UPDATE account SET balance = 0 WHERE id = 1;
                                             -- waits: same row, write-write conflict
COMMIT;                                      -- B's update now proceeds

-- Deadlock: A locks 1 then 2, B locks 2 then 1 -> one is aborted with
-- ERROR: deadlock detected. Fix: always lock rows in id order.
SELECT * FROM account WHERE id IN (1, 2) ORDER BY id FOR UPDATE;

CREATE TABLE measurement (
    sensor_id int NOT NULL,
    taken_at  timestamptz NOT NULL,
    value     double precision
) PARTITION BY RANGE (taken_at);

CREATE TABLE measurement_2026_04 PARTITION OF measurement
    FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE measurement_2026_05 PARTITION OF measurement
    FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');

EXPLAIN SELECT avg(value) FROM measurement
WHERE taken_at >= '2026-05-10' AND taken_at < '2026-05-11';
-- only measurement_2026_05 is scanned (partition pruning)

DROP TABLE measurement_2026_04;   -- retention: instant, no bulk DELETE

-- Transactional outbox: data change and event committed atomically
CREATE TABLE orders (id bigint PRIMARY KEY, status text NOT NULL);
CREATE TABLE outbox (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    topic      text NOT NULL,
    payload    jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    sent_at    timestamptz
);
BEGIN;
INSERT INTO orders VALUES (42, 'placed');
INSERT INTO outbox (topic, payload)
VALUES ('order.placed', '{"order_id": 42}');
COMMIT;

-- relay process: claim a batch, publish to the broker, mark as sent
SELECT id, topic, payload FROM outbox
WHERE sent_at IS NULL ORDER BY id LIMIT 100 FOR UPDATE SKIP LOCKED;
